// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, uint256 fund) public {
        fund = bound(fund, 0, 1 ether);

        vm.deal(caller, fund);
        if (fund > 0) {
            (bool sent, ) = address(c).call{value: fund}("");
            require(sent);
        }

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(address(0xBEEF)) {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = c.owner();
        if (caller == owner) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}
